/**
 * Pure renderers for the generated native colour files (lane N-A).
 * Input is `nativeTokens` from `@munib-tracker/theme/native-tokens`; output is a
 * map of `{ path relative to apps/app: file contents }`. Used by
 * `scripts/generate-native-tokens.mjs` (writes) and `plugins/nativeTokens.test.js` (drift).
 * Plain Node, no dependencies, LF newlines.
 */

const GENERATED_BY = "scripts/generate-native-tokens.mjs";
const HEADER =
  "GENERATED by apps/app/scripts/generate-native-tokens.mjs from packages/theme/src/native-tokens.ts.\n" +
  "DO NOT EDIT. Regenerate: pnpm --filter app generate:native-tokens";

const OUTPUTS = {
  swift: "targets/_shared/MunibTokens.generated.swift",
  widgetTs: "src/lib/appSurfaces/widgets/widgetTokens.generated.ts",
  json: "plugins/generated/native-tokens.json",
  wear: "plugins/wear-os/src/main/java/expo/modules/munibwear/WearTokens.generated.kt",
};

const up = (hex) => hex.toUpperCase();
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

function channels(hex) {
  const n = Number.parseInt(hex.slice(1), 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function swiftColor(hex) {
  const [r, g, b] = channels(hex).map((c) => (c / 255).toFixed(4));
  return `Color(red: ${r}, green: ${g}, blue: ${b}) // ${up(hex)}`;
}

function renderSwift(t) {
  const lines = [];
  for (const scheme of ["light", "dark"]) {
    for (const [key, hex] of Object.entries(t[scheme])) {
      lines.push(`  static let ${scheme}${cap(key)} = ${swiftColor(hex)}`);
    }
    lines.push("");
  }
  for (const [key, hex] of Object.entries(t.status)) {
    lines.push(`  static let status${cap(key)} = ${swiftColor(hex)}`);
  }
  lines.push(`  static let dangerOnFill = ${swiftColor(t.danger.onFill)}`);
  return `// ${HEADER.split("\n").join("\n// ")}\n\nimport SwiftUI\n\n/// Colour-only palette mirrored from the app theme (default forest accent).\n/// Used before the first widget snapshot and when Appearance follows the system.\nenum MunibTokens {\n${lines.join("\n")}\n}\n`;
}

function renderWidgetTs(t) {
  const surface = (s) => ({
    background: up(s.background),
    cardBackground: up(s.card),
    textPrimary: up(s.text),
    textSecondary: up(s.textSecondary),
    border: up(s.border),
  });
  const obj = (name, value) => {
    const body = Object.entries(value)
      .map(([k, v]) => `  ${k}: ${JSON.stringify(v)},`)
      .join("\n");
    return `export const ${name} = {\n${body}\n} as const;\n`;
  };
  const status = Object.fromEntries(Object.entries(t.status).map(([k, v]) => [k, up(v)]));
  return [
    `// ${HEADER.split("\n").join("\n// ")}\n`,
    obj("WIDGET_LIGHT", surface(t.light)),
    obj("WIDGET_DARK", surface(t.dark)),
    obj("WIDGET_DEFAULT_ACCENT", {
      light: up(t.defaultAccent.light),
      dark: up(t.defaultAccent.dark),
    }),
    obj("WIDGET_STATUS", status),
  ].join("\n");
}

function renderJson(t) {
  return `${JSON.stringify({ _generated: `${HEADER.replaceAll("\n", " ")}`, ...t }, null, 2)}\n`;
}

function kt(hex) {
  return `0xFF${up(hex).slice(1)}.toInt()`;
}

function renderWear(t) {
  const d = t.dark;
  return `// ${HEADER.split("\n").join("\n// ")}\n\npackage expo.modules.munibwear\n\n/** Dark palette only — Wear UI is dark by convention. */\ninternal object WearTokens {\n  const val TEXT = ${kt(d.text)}\n  const val SECONDARY = ${kt(d.textSecondary)}\n  const val ACCENT = ${kt(t.defaultAccent.dark)}\n  const val CARD = ${kt(d.card)}\n  const val MUTED = ${kt(d.muted)}\n  const val SUCCESS = ${kt(t.status.success)}\n  const val WARNING = ${kt(t.status.warning)}\n}\n`;
}

function renderAll(tokens) {
  return {
    [OUTPUTS.swift]: renderSwift(tokens),
    [OUTPUTS.widgetTs]: renderWidgetTs(tokens),
    [OUTPUTS.json]: renderJson(tokens),
    [OUTPUTS.wear]: renderWear(tokens),
  };
}

module.exports = { renderAll, OUTPUTS, GENERATED_BY };
